@font-face {
  font-family: "Bungee";
  src: url("assets/fonts/bungee.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}
@font-face {
  font-family: "Outfit";
  src: url("assets/fonts/outfit.woff2") format("woff2");
  font-style: normal;
  font-weight: 100 900;
  font-display: swap;
}

:root {
  --ink: #100b21;
  --ink-soft: #211839;
  --cream: #fff5d6;
  --yellow: #d9ff45;
  --yellow-deep: #b7e51d;
  --pink: #ff3d77;
  --pink-deep: #c91652;
  --cyan: #58efff;
  --purple: #8a6bff;
  --glass: rgba(20, 14, 38, 0.74);
  --glass-line: rgba(255, 255, 255, 0.14);
  --display: "Bungee", "Arial Black", Impact, sans-serif;
  --body: "Outfit", "Segoe UI", system-ui, sans-serif;
  --safe-top: max(14px, env(safe-area-inset-top));
  --safe-bottom: max(14px, env(safe-area-inset-bottom));
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  width: 100%;
  height: 100%;
  margin: 0;
  overflow: hidden;
  background: #0b0718;
  color: var(--cream);
  font-family: var(--body);
  overscroll-behavior: none;
  touch-action: none;
  -webkit-user-select: none;
  user-select: none;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 3px solid var(--cyan);
  outline-offset: 4px;
}

#game {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
  background: linear-gradient(180deg, #1a123d 0%, #602a64 55%, #1b1025 100%);
}

.world-shade,
.scanlines,
.coin-layer {
  position: fixed;
  inset: 0;
  pointer-events: none;
}

.world-shade {
  background:
    radial-gradient(120% 86% at 50% 45%, transparent 44%, rgba(8, 4, 18, 0.25) 100%),
    linear-gradient(180deg, rgba(6, 3, 16, 0.14), transparent 20%, transparent 76%, rgba(7, 3, 17, 0.42));
  z-index: 2;
}

.scanlines {
  z-index: 3;
  opacity: 0.1;
  background: repeating-linear-gradient(180deg, transparent 0 3px, rgba(0, 0, 0, 0.18) 4px);
  mix-blend-mode: multiply;
}

.coin-layer {
  z-index: 40;
  overflow: hidden;
}

.coin-layer .fly-coin {
  position: absolute;
  width: 22px;
  height: 22px;
  border-radius: 50%;
  background: radial-gradient(circle at 35% 30%, #fff7ba 0 18%, #ffd93d 20% 58%, #eb9412 62% 100%);
  border: 2px solid rgba(71, 36, 3, 0.55);
  box-shadow: 0 0 16px rgba(255, 208, 51, 0.7);
  transform: translate(-50%, -50%);
  animation: coin-flight 0.72s cubic-bezier(0.3, 0.1, 0.65, 1) forwards;
}

@keyframes coin-flight {
  0% { opacity: 0; scale: 0.4; }
  12% { opacity: 1; scale: 1.15; }
  100% { opacity: 0; translate: var(--dx, 0) var(--dy, -180px); scale: 0.55; }
}

/* ---------- In-game HUD ---------- */

.game-hud {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: calc(var(--safe-top) + 2px) max(16px, env(safe-area-inset-right)) var(--safe-bottom) max(16px, env(safe-area-inset-left));
  pointer-events: none;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.28s ease, visibility 0.28s;
}

body.in-game .game-hud {
  opacity: 1;
  visibility: visible;
}

body.paused .game-hud {
  opacity: 0.22;
}

.hud-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 12px;
}

.sector-pill {
  position: relative;
  display: flex;
  flex-direction: column;
  min-width: 150px;
  padding: 9px 15px 10px 18px;
  background: linear-gradient(100deg, rgba(16, 10, 33, 0.9), rgba(16, 10, 33, 0.5));
  border-left: 4px solid var(--yellow);
  clip-path: polygon(0 0, 100% 0, calc(100% - 12px) 100%, 0 100%);
  filter: drop-shadow(0 4px 10px rgba(0, 0, 0, 0.3));
}

.sector-kicker {
  color: var(--yellow);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.2em;
  line-height: 1;
}

.sector-kicker b {
  color: var(--cream);
}

.sector-pill strong {
  margin-top: 4px;
  font-family: var(--display);
  font-size: 17px;
  line-height: 1;
  letter-spacing: 0.01em;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.35);
}

.hud-actions {
  display: flex;
  align-items: center;
  gap: 8px;
  pointer-events: auto;
}

.coin-pill {
  display: flex;
  align-items: center;
  gap: 7px;
  height: 39px;
  min-width: 82px;
  padding: 0 13px 0 8px;
  border: 1.5px solid rgba(255, 255, 255, 0.17);
  border-radius: 999px;
  background: rgba(14, 9, 29, 0.74);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.13), 0 5px 18px rgba(0, 0, 0, 0.25);
  font-family: var(--display);
  font-size: 16px;
  letter-spacing: 0.03em;
  backdrop-filter: blur(10px);
}

.coin-pill.large {
  height: 45px;
  font-size: 18px;
  padding-right: 17px;
}

.coin-glyph {
  width: 25px;
  height: 25px;
  flex: 0 0 auto;
  filter: drop-shadow(0 0 8px rgba(255, 210, 55, 0.35));
}

.icon-button {
  width: 39px;
  height: 39px;
  display: grid;
  place-items: center;
  border-radius: 12px;
  border: 1.5px solid rgba(255, 255, 255, 0.15);
  background: rgba(14, 9, 29, 0.72);
  color: var(--cream);
  backdrop-filter: blur(10px);
  transition: transform 0.16s, background 0.16s;
}

.icon-button:hover {
  background: rgba(34, 24, 58, 0.9);
}

.icon-button:active {
  transform: scale(0.92);
}

.icon-button svg {
  width: 21px;
  height: 21px;
}

.sound-off,
body.muted .sound-on {
  display: none;
}

body.muted .sound-off {
  display: block;
}

.pause-button {
  display: flex;
  gap: 4px;
  align-items: center;
  justify-content: center;
}

.pause-button span {
  width: 4px;
  height: 15px;
  border-radius: 2px;
  background: var(--cream);
}

.center-hud {
  position: absolute;
  top: calc(var(--safe-top) + 61px);
  left: 50%;
  width: min(460px, calc(100vw - 40px));
  transform: translateX(-50%);
}

.wave-hud {
  padding: 7px 12px 9px;
  border-radius: 12px;
  background: rgba(13, 8, 26, 0.52);
  border: 1px solid rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(8px);
  transition: opacity 0.25s, transform 0.25s;
}

.wave-hud.hidden {
  opacity: 0;
  transform: translateY(-8px);
}

.wave-copy {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  margin-bottom: 5px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.wave-copy span:first-child {
  color: var(--cream);
}

.wave-copy span:last-child {
  color: var(--yellow);
}

.wave-track {
  height: 6px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.12);
}

#waveFill {
  height: 100%;
  width: 0;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--cyan), var(--yellow));
  box-shadow: 0 0 10px rgba(88, 239, 255, 0.55);
  transition: width 0.16s linear;
}

.boss-hud {
  padding: 9px 14px 11px;
  border-radius: 13px;
  background: linear-gradient(100deg, rgba(46, 5, 31, 0.82), rgba(18, 8, 30, 0.82));
  border: 1px solid rgba(255, 76, 123, 0.48);
  box-shadow: 0 0 28px rgba(255, 28, 99, 0.14), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  opacity: 0;
  transform: translateY(-8px);
  visibility: hidden;
  transition: opacity 0.3s, transform 0.3s, visibility 0.3s;
}

.boss-hud.show {
  opacity: 1;
  transform: none;
  visibility: visible;
}

.boss-heading {
  display: flex;
  align-items: baseline;
  gap: 9px;
  margin-bottom: 6px;
}

.boss-heading span {
  color: var(--pink);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.2em;
}

.boss-heading strong {
  font-family: var(--display);
  font-size: 16px;
  letter-spacing: 0.03em;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.35);
}

.boss-track {
  position: relative;
  height: 9px;
  overflow: hidden;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.13);
}

#bossFill {
  height: 100%;
  width: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #ff8c3c, #ff3d77 50%, #d21b6a);
  box-shadow: 0 0 14px rgba(255, 42, 104, 0.6);
  transition: width 0.08s linear;
}

.boss-glint {
  position: absolute;
  inset: 0;
  background: linear-gradient(100deg, transparent 30%, rgba(255, 255, 255, 0.35) 50%, transparent 65%);
  transform: translateX(-100%);
  animation: boss-glint 2.6s linear infinite;
}

@keyframes boss-glint {
  to { transform: translateX(100%); }
}

.hud-bottom {
  display: grid;
  grid-template-columns: minmax(150px, 270px) 1fr minmax(130px, 220px);
  align-items: end;
  gap: 24px;
}

.health-card {
  padding: 10px 13px 12px;
  border-radius: 14px 14px 14px 4px;
  background: rgba(13, 8, 26, 0.67);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.1);
  backdrop-filter: blur(9px);
}

.health-top {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 6px;
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.health-top span {
  color: rgba(255, 245, 214, 0.72);
}

.health-top b {
  color: var(--yellow);
  font-family: var(--display);
  font-size: 16px;
  letter-spacing: 0;
}

.health-track {
  position: relative;
  height: 12px;
  overflow: hidden;
  border-radius: 4px;
  background: rgba(255, 255, 255, 0.13);
  border: 1px solid rgba(0, 0, 0, 0.2);
}

#hpFill {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #ff4b72, #ff8554 48%, var(--yellow));
  box-shadow: 0 0 12px rgba(255, 84, 100, 0.4);
  transition: width 0.18s ease;
}

.health-card.low #hpFill {
  background: linear-gradient(90deg, #ff204a, #ff5e38);
  animation: low-pulse 0.75s ease-in-out infinite alternate;
}

@keyframes low-pulse {
  to { filter: brightness(1.45); }
}

.health-shine {
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.22), transparent 55%);
}

.weapon-card {
  justify-self: end;
  min-width: 158px;
  padding: 9px 13px 10px;
  text-align: right;
  border-radius: 14px 14px 4px 14px;
  background: rgba(13, 8, 26, 0.66);
  border: 1px solid rgba(88, 239, 255, 0.2);
  backdrop-filter: blur(9px);
}

.weapon-kicker {
  display: block;
  color: rgba(88, 239, 255, 0.7);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.19em;
}

.weapon-card strong {
  display: block;
  margin: 2px 0 1px;
  color: var(--cyan);
  font-family: var(--display);
  font-size: 16px;
  letter-spacing: 0.02em;
}

.weapon-card > span:last-child {
  color: rgba(255, 245, 214, 0.52);
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 0.12em;
}

.combo-hud {
  justify-self: center;
  align-self: end;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: 106px;
  margin-bottom: 2px;
  opacity: 0;
  transform: translateY(8px) scale(0.9);
  transition: opacity 0.2s, transform 0.2s;
}

.combo-hud.show {
  opacity: 1;
  transform: none;
}

.combo-x {
  color: var(--pink);
  font-family: var(--display);
  font-size: 19px;
  line-height: 1;
  text-shadow: 0 2px 0 rgba(0, 0, 0, 0.35);
}

.combo-x b {
  font-size: 30px;
  font-weight: 400;
}

.combo-label {
  color: var(--cream);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.28em;
  margin: 2px 0 5px;
}

.combo-track {
  width: 100%;
  height: 3px;
  border-radius: 999px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.14);
}

#comboFill {
  width: 100%;
  height: 100%;
  background: var(--pink);
  transform-origin: left;
}

.aim-hint {
  position: absolute;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 70px);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 14px 7px 10px;
  border-radius: 999px;
  background: rgba(12, 7, 25, 0.62);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: rgba(255, 245, 214, 0.68);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.09em;
  transform: translateX(-50%);
  transition: opacity 0.5s;
  white-space: nowrap;
  backdrop-filter: blur(8px);
}

.aim-hint b {
  color: var(--yellow);
}

.aim-hint.hide {
  opacity: 0;
}

.swipe-mark {
  display: grid;
  place-items: center;
  width: 21px;
  height: 21px;
  border-radius: 50%;
  color: var(--ink);
  background: var(--yellow);
  font-size: 12px;
  font-weight: 900;
}

/* ---------- Stage banner / toast ---------- */

.stage-banner {
  position: fixed;
  z-index: 25;
  top: 21%;
  left: 50%;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-width: min(320px, 84vw);
  padding: 13px 30px 15px;
  color: var(--cream);
  background: linear-gradient(100deg, transparent, rgba(13, 8, 26, 0.78) 14%, rgba(13, 8, 26, 0.78) 86%, transparent);
  border-top: 1px solid rgba(255, 255, 255, 0.14);
  border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  transform: translate(-50%, -12px) scale(0.96);
  opacity: 0;
  pointer-events: none;
}

.stage-banner.show {
  animation: banner-in 2.9s cubic-bezier(0.2, 0.9, 0.25, 1) both;
}

.stage-banner.boss {
  border-color: rgba(255, 61, 119, 0.55);
  background: linear-gradient(100deg, transparent, rgba(56, 7, 38, 0.9) 14%, rgba(56, 7, 38, 0.9) 86%, transparent);
}

.stage-banner span {
  color: var(--yellow);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.28em;
}

.stage-banner.boss span {
  color: var(--pink);
}

.stage-banner strong {
  font-family: var(--display);
  font-size: clamp(24px, 4.2vw, 42px);
  line-height: 1.08;
  letter-spacing: 0.01em;
  text-align: center;
  text-shadow: 0 3px 0 rgba(0, 0, 0, 0.35);
}

.stage-banner em {
  margin-top: 3px;
  color: rgba(255, 245, 214, 0.55);
  font-size: 9px;
  font-style: normal;
  font-weight: 800;
  letter-spacing: 0.22em;
}

@keyframes banner-in {
  0% { opacity: 0; transform: translate(-50%, 4px) scale(0.9); }
  10%, 76% { opacity: 1; transform: translate(-50%, 0) scale(1); }
  100% { opacity: 0; transform: translate(-50%, -14px) scale(1.02); }
}

.toast {
  position: fixed;
  z-index: 60;
  left: 50%;
  bottom: calc(var(--safe-bottom) + 122px);
  padding: 10px 18px;
  border-radius: 999px;
  background: rgba(11, 7, 23, 0.92);
  border: 1px solid rgba(217, 255, 69, 0.45);
  color: var(--yellow);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.08em;
  white-space: nowrap;
  opacity: 0;
  transform: translate(-50%, 8px);
  pointer-events: none;
  transition: opacity 0.2s, transform 0.2s;
  box-shadow: 0 8px 28px rgba(0, 0, 0, 0.34);
}

.toast.show {
  opacity: 1;
  transform: translate(-50%, 0);
}

/* ---------- Title screen ---------- */

.screen {
  position: fixed;
  inset: 0;
  z-index: 30;
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transition: opacity 0.35s ease, visibility 0.35s;
}

.screen.show {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

.title-screen {
  display: flex;
  flex-direction: column;
  justify-content: center;
  padding: calc(var(--safe-top) + 22px) max(6vw, 28px) calc(var(--safe-bottom) + 20px);
  background:
    linear-gradient(90deg, rgba(10, 6, 22, 0.94) 0%, rgba(10, 6, 22, 0.72) 34%, rgba(10, 6, 22, 0.04) 68%),
    linear-gradient(0deg, rgba(9, 5, 20, 0.8) 0%, transparent 35%),
    radial-gradient(90% 70% at 72% 45%, rgba(255, 105, 85, 0.08), transparent 60%);
}

.title-brand {
  position: absolute;
  top: calc(var(--safe-top) + 8px);
  left: max(6vw, 28px);
  display: flex;
  align-items: center;
  gap: 12px;
}

.mini-mark {
  display: flex;
  align-items: center;
  gap: 5px;
  font-family: var(--display);
  font-size: 17px;
  color: var(--cream);
  line-height: 1;
}

.mark-slash {
  width: 5px;
  height: 21px;
  display: inline-block;
  background: var(--yellow);
  transform: skewX(-16deg);
}

.brand-note {
  padding-left: 12px;
  border-left: 1px solid rgba(255, 255, 255, 0.2);
  color: rgba(255, 245, 214, 0.42);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.22em;
}

.title-content {
  position: relative;
  width: min(620px, 49vw);
  margin-left: max(3vw, 0px);
  animation: title-rise 0.8s 0.1s cubic-bezier(0.2, 0.8, 0.2, 1) both;
}

@keyframes title-rise {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: none; }
}

.title-kicker {
  display: flex;
  align-items: center;
  gap: 11px;
  color: var(--yellow);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.25em;
  margin-bottom: 9px;
}

.title-kicker span {
  width: 28px;
  height: 2px;
  background: var(--yellow);
  box-shadow: 0 0 10px rgba(217, 255, 69, 0.65);
}

.logo-wrap {
  position: relative;
  display: inline-block;
  transform: rotate(-1.4deg);
}

.game-logo {
  position: relative;
  z-index: 1;
  margin: 0;
  font-family: var(--display);
  font-size: clamp(72px, 10.5vw, 156px);
  line-height: 0.84;
  letter-spacing: -0.035em;
  color: var(--cream);
  -webkit-text-stroke: clamp(2px, 0.3vw, 5px) var(--ink);
  paint-order: stroke fill;
  text-shadow:
    0 clamp(4px, 0.7vw, 10px) 0 var(--ink),
    0 clamp(9px, 1.2vw, 18px) 0 rgba(0, 0, 0, 0.24);
}

.game-logo span {
  color: var(--yellow);
  margin-left: 0.015em;
}

.logo-ribbon {
  position: absolute;
  z-index: 2;
  right: 1%;
  bottom: -15px;
  padding: 7px 14px 6px 18px;
  background: var(--pink);
  color: var(--cream);
  font-family: var(--display);
  font-size: clamp(13px, 1.55vw, 21px);
  letter-spacing: 0.1em;
  transform: rotate(2.2deg);
  box-shadow: 4px 5px 0 var(--pink-deep), 0 10px 24px rgba(0, 0, 0, 0.25);
}

.logo-ribbon::after {
  content: "";
  position: absolute;
  right: -13px;
  top: 0;
  border-top: 17px solid var(--pink);
  border-bottom: 16px solid var(--pink);
  border-right: 14px solid transparent;
}

.title-tagline {
  margin: 34px 0 22px;
  color: rgba(255, 245, 214, 0.66);
  font-size: clamp(13px, 1.2vw, 16px);
  font-weight: 700;
  line-height: 1.38;
  letter-spacing: 0.06em;
}

.title-tagline b {
  color: var(--cream);
  font-weight: 700;
}

.title-actions {
  display: flex;
  align-items: stretch;
  gap: 12px;
}

.mega-button,
.primary-button,
.secondary-button,
.ghost-button,
.text-button {
  position: relative;
  border-radius: 0;
  transition: transform 0.15s ease, filter 0.15s ease;
}

.mega-button {
  display: flex;
  align-items: center;
  gap: 13px;
  min-width: 208px;
  padding: 15px 72px 15px 22px;
  background: var(--yellow);
  color: var(--ink);
  text-align: left;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%);
  box-shadow: inset 0 -6px 0 rgba(89, 111, 0, 0.18);
}

.mega-button::after,
.primary-button::after {
  content: "";
  position: absolute;
  right: 16px;
  top: 50%;
  width: 36px;
  height: 2px;
  background: currentColor;
  opacity: 0.35;
}

.mega-button:hover,
.primary-button:hover {
  filter: brightness(1.08);
  transform: translateY(-2px);
}

.mega-button:active,
.primary-button:active,
.secondary-button:active {
  transform: translateY(1px) scale(0.985);
}

.play-triangle {
  width: 0;
  height: 0;
  border-top: 10px solid transparent;
  border-bottom: 10px solid transparent;
  border-left: 15px solid var(--ink);
  flex: 0 0 auto;
}

.mega-label {
  font-family: var(--display);
  font-size: 25px;
  line-height: 1;
  letter-spacing: 0.03em;
}

.mega-sub {
  position: absolute;
  right: 16px;
  bottom: 9px;
  color: rgba(16, 11, 33, 0.5);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.mega-sub b {
  color: var(--ink);
}

.secondary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 9px;
  min-width: 146px;
  padding: 0 18px;
  border: 1.5px solid rgba(255, 255, 255, 0.24);
  background: rgba(16, 10, 32, 0.55);
  color: var(--cream);
  font-size: 11px;
  font-weight: 900;
  letter-spacing: 0.14em;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
  backdrop-filter: blur(10px);
}

.secondary-button svg {
  width: 21px;
  height: 21px;
  color: var(--yellow);
}

.secondary-button:hover {
  background: rgba(35, 24, 55, 0.78);
  border-color: rgba(255, 255, 255, 0.42);
}

.button-coins {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 29px;
  height: 21px;
  margin-left: 2px;
  padding: 0 7px;
  border-radius: 999px;
  background: rgba(255, 217, 61, 0.15);
  color: #ffd93d;
  font-size: 10px;
  letter-spacing: 0;
}

.control-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 18px;
  margin-top: 25px;
  color: rgba(255, 245, 214, 0.46);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.13em;
}

.control-strip span {
  display: flex;
  align-items: center;
  gap: 6px;
}

.dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
}

.dot-cyan { background: var(--cyan); box-shadow: 0 0 7px var(--cyan); }
.dot-yellow { background: var(--yellow); box-shadow: 0 0 7px var(--yellow); }
.dot-pink { background: var(--pink); box-shadow: 0 0 7px var(--pink); }

.title-bottom {
  position: absolute;
  left: max(6vw, 28px);
  right: max(6vw, 28px);
  bottom: calc(var(--safe-bottom) + 10px);
  display: flex;
  justify-content: space-between;
  color: rgba(255, 245, 214, 0.27);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.18em;
}

/* ---------- Modal screens ---------- */

.modal-screen {
  display: grid;
  place-items: center;
  padding: 22px;
  background: radial-gradient(80% 80% at 50% 40%, rgba(30, 16, 52, 0.55), rgba(7, 4, 15, 0.87));
  backdrop-filter: blur(7px) saturate(0.85);
}

.modal-card {
  position: relative;
  width: min(480px, 100%);
  padding: clamp(28px, 5vw, 48px);
  overflow: hidden;
  background:
    linear-gradient(155deg, rgba(35, 23, 58, 0.94), rgba(16, 10, 31, 0.97)),
    var(--ink);
  border: 1px solid rgba(255, 255, 255, 0.13);
  box-shadow: 0 28px 70px rgba(0, 0, 0, 0.5), inset 0 1px 0 rgba(255, 255, 255, 0.1);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 22px), calc(100% - 22px) 100%, 0 100%);
  animation: modal-pop 0.34s cubic-bezier(0.18, 0.9, 0.28, 1.15) both;
}

@keyframes modal-pop {
  from { opacity: 0; transform: translateY(18px) scale(0.97); }
  to { opacity: 1; transform: none; }
}

.modal-card::before {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 84px;
  height: 4px;
  background: var(--yellow);
}

.eyebrow {
  display: block;
  color: var(--yellow);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.25em;
}

.eyebrow.danger {
  color: var(--pink);
}

.modal-card h2 {
  margin: 10px 0 16px;
  font-family: var(--display);
  font-size: clamp(42px, 7vw, 68px);
  line-height: 0.88;
  letter-spacing: -0.02em;
  color: var(--cream);
  text-shadow: 0 4px 0 rgba(0, 0, 0, 0.3);
}

.clear-card h2 span {
  color: var(--yellow);
}

.dead-card h2 {
  color: var(--pink);
  font-size: clamp(52px, 8vw, 82px);
}

.modal-copy {
  margin: 0 0 24px;
  color: rgba(255, 245, 214, 0.6);
  font-size: 14px;
  font-weight: 500;
  line-height: 1.55;
}

.modal-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
  margin-top: 24px;
}

.primary-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  min-height: 52px;
  padding: 0 52px 0 24px;
  background: var(--yellow);
  color: var(--ink);
  font-family: var(--display);
  font-size: 14px;
  letter-spacing: 0.03em;
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 10px), calc(100% - 10px) 100%, 0 100%);
}

.primary-button span {
  font-family: var(--body);
  font-size: 20px;
  line-height: 1;
}

.primary-button.small {
  min-height: 44px;
  font-size: 11px;
  padding: 0 38px 0 18px;
}

.primary-button.wide,
.secondary-button.wide {
  width: 100%;
}

.ghost-button {
  min-height: 52px;
  padding: 0 20px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: transparent;
  color: rgba(255, 245, 214, 0.75);
  font-size: 10px;
  font-weight: 900;
  letter-spacing: 0.12em;
}

.ghost-button:hover {
  background: rgba(255, 255, 255, 0.06);
}

.text-button {
  min-height: 40px;
  padding: 0 8px;
  background: transparent;
  color: rgba(255, 245, 214, 0.42);
  font-size: 9px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

.text-button:hover {
  color: var(--cream);
}

.result-stats {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1px;
  margin: 26px 0 4px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  background: rgba(255, 255, 255, 0.11);
}

.result-stats > div {
  padding: 14px 12px;
  background: rgba(15, 9, 29, 0.72);
}

.result-stats span {
  display: block;
  margin-bottom: 5px;
  color: rgba(255, 245, 214, 0.4);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.result-stats b {
  font-family: var(--display);
  font-size: clamp(19px, 3.5vw, 25px);
  color: var(--yellow);
  font-weight: 400;
}

.result-stats.compact {
  margin-top: 6px;
}

.result-burst {
  position: absolute;
  right: -100px;
  top: -110px;
  width: 280px;
  height: 280px;
  border-radius: 50%;
  background: repeating-conic-gradient(from 0deg, rgba(217, 255, 69, 0.15) 0 8deg, transparent 8deg 18deg);
  mask-image: radial-gradient(circle, transparent 0 40%, black 41%);
  animation: burst-spin 24s linear infinite;
  pointer-events: none;
}

@keyframes burst-spin {
  to { transform: rotate(1turn); }
}

/* ---------- Armory ---------- */

.armory-screen {
  display: flex;
  justify-content: center;
  align-items: stretch;
  padding: calc(var(--safe-top) + 12px) 14px calc(var(--safe-bottom) + 12px);
  background: radial-gradient(120% 100% at 60% 0%, rgba(83, 49, 111, 0.45), rgba(7, 4, 16, 0.91));
  backdrop-filter: blur(9px);
}

.armory-panel {
  width: min(820px, 100%);
  max-height: 100%;
  overflow-y: auto;
  overscroll-behavior: contain;
  touch-action: pan-y;
  padding: clamp(20px, 3vw, 34px);
  background:
    linear-gradient(145deg, rgba(32, 22, 53, 0.97), rgba(14, 9, 28, 0.98)),
    var(--ink);
  border: 1px solid rgba(255, 255, 255, 0.12);
  box-shadow: 0 30px 90px rgba(0, 0, 0, 0.5);
  clip-path: polygon(0 0, 100% 0, 100% calc(100% - 20px), calc(100% - 20px) 100%, 0 100%);
  scrollbar-width: thin;
  scrollbar-color: rgba(217, 255, 69, 0.35) transparent;
}

.armory-panel::-webkit-scrollbar {
  width: 5px;
}

.armory-panel::-webkit-scrollbar-thumb {
  background: rgba(217, 255, 69, 0.35);
}

.armory-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 16px;
}

.armory-head h2 {
  margin: 7px 0 0;
  font-family: var(--display);
  font-size: clamp(31px, 5vw, 45px);
  line-height: 1;
  color: var(--cream);
}

.armory-head-right {
  display: flex;
  align-items: center;
  gap: 10px;
}

.close-button {
  width: 42px;
  height: 42px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.04);
  color: rgba(255, 245, 214, 0.7);
  font-size: 18px;
}

.close-button:hover {
  background: rgba(255, 61, 119, 0.18);
  color: var(--cream);
}

.armory-intro {
  margin: 10px 0 24px;
  color: rgba(255, 245, 214, 0.45);
  font-size: 12px;
  font-weight: 600;
  letter-spacing: 0.04em;
}

.section-label {
  display: flex;
  align-items: center;
  gap: 12px;
  margin: 22px 0 12px;
  color: rgba(255, 245, 214, 0.55);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.21em;
}

.section-label i {
  flex: 1;
  height: 1px;
  background: rgba(255, 255, 255, 0.1);
}

.weapon-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
}

.weapon-item {
  position: relative;
  display: flex;
  flex-direction: column;
  min-height: 140px;
  padding: 14px;
  text-align: left;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.055), rgba(255, 255, 255, 0.018));
  border: 1px solid rgba(255, 255, 255, 0.1);
  transition: border-color 0.18s, background 0.18s;
  overflow: hidden;
}

.weapon-item::after {
  content: "";
  position: absolute;
  right: -15px;
  bottom: -28px;
  width: 95px;
  height: 95px;
  border-radius: 50%;
  background: var(--weapon-color, var(--cyan));
  opacity: 0.06;
  filter: blur(2px);
}

.weapon-item.equipped {
  border-color: var(--weapon-color, var(--cyan));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.04), 0 0 18px color-mix(in srgb, var(--weapon-color, var(--cyan)) 14%, transparent);
}

.weapon-item.locked {
  opacity: 0.84;
}

.weapon-item .weapon-glyph {
  width: 69px;
  height: 32px;
  color: var(--weapon-color, var(--cyan));
  margin-bottom: 7px;
  filter: drop-shadow(0 0 8px color-mix(in srgb, var(--weapon-color, var(--cyan)) 30%, transparent));
}

.weapon-name-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
}

.weapon-name-row strong {
  font-family: var(--display);
  font-size: 15px;
  font-weight: 400;
  letter-spacing: 0.01em;
}

.weapon-tag {
  color: rgba(255, 245, 214, 0.43);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.13em;
  margin-top: 2px;
}

.weapon-stats {
  display: flex;
  gap: 12px;
  margin: 9px 0 10px;
  color: rgba(255, 245, 214, 0.44);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.weapon-stats b {
  color: rgba(255, 245, 214, 0.82);
  font-weight: 800;
}

.weapon-action {
  margin-top: auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  min-height: 29px;
  padding: 0 10px;
  border: 1px solid rgba(255, 255, 255, 0.11);
  background: rgba(255, 255, 255, 0.045);
  color: rgba(255, 245, 214, 0.7);
  font-size: 8px;
  font-weight: 900;
  letter-spacing: 0.14em;
}

.weapon-item.equipped .weapon-action {
  background: color-mix(in srgb, var(--weapon-color, var(--cyan)) 14%, transparent);
  border-color: color-mix(in srgb, var(--weapon-color, var(--cyan)) 34%, transparent);
  color: var(--weapon-color, var(--cyan));
}

.weapon-item.weapon-buyable .weapon-action {
  border-color: rgba(255, 217, 61, 0.35);
  color: #ffd93d;
}

.weapon-action .mini-coin {
  width: 11px;
  height: 11px;
  margin-right: 3px;
  border-radius: 50%;
  background: #ffd93d;
  display: inline-block;
  vertical-align: -1px;
}

.weapon-item.weapon-buyable:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(255, 217, 61, 0.4);
}

.weapon-item.weapon-locked:hover {
  border-color: rgba(255, 255, 255, 0.18);
}

.upgrade-list {
  display: grid;
  gap: 8px;
}

.upgrade-item {
  display: grid;
  grid-template-columns: 43px 1fr auto;
  align-items: center;
  gap: 12px;
  width: 100%;
  min-height: 66px;
  padding: 10px 13px;
  text-align: left;
  background: rgba(255, 255, 255, 0.035);
  border: 1px solid rgba(255, 255, 255, 0.09);
  transition: background 0.16s, border-color 0.16s;
}

.upgrade-item:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.065);
  border-color: rgba(217, 255, 69, 0.27);
}

.upgrade-item:disabled {
  cursor: default;
}

.upgrade-icon {
  display: grid;
  place-items: center;
  width: 43px;
  height: 43px;
  background: rgba(217, 255, 69, 0.09);
  border: 1px solid rgba(217, 255, 69, 0.16);
  color: var(--yellow);
  font-family: var(--display);
  font-size: 15px;
}

.upgrade-copy strong {
  display: block;
  color: var(--cream);
  font-size: 12px;
  font-weight: 800;
  letter-spacing: 0.11em;
}

.upgrade-copy span {
  display: block;
  margin-top: 3px;
  color: rgba(255, 245, 214, 0.4);
  font-size: 10px;
  font-weight: 500;
  letter-spacing: 0.02em;
}

.upgrade-pips {
  display: flex;
  gap: 3px;
  margin-top: 6px;
}

.upgrade-pips i {
  width: 13px;
  height: 3px;
  border-radius: 3px;
  background: rgba(255, 255, 255, 0.12);
}

.upgrade-pips i.on {
  background: var(--yellow);
  box-shadow: 0 0 5px rgba(217, 255, 69, 0.5);
}

.upgrade-buy {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 84px;
  justify-content: flex-end;
  color: #ffd93d;
  font-family: var(--display);
  font-size: 13px;
}

.upgrade-buy.max {
  color: rgba(255, 245, 214, 0.35);
  font-family: var(--body);
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.13em;
}

.upgrade-buy.cant {
  color: rgba(255, 217, 61, 0.38);
}

.armory-foot {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 12px;
  margin-top: 26px;
  padding-top: 16px;
  border-top: 1px solid rgba(255, 255, 255, 0.09);
}

.armory-foot > span {
  color: rgba(255, 245, 214, 0.28);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.16em;
}

/* ---------- Utility ---------- */

.rotate-hint {
  display: none;
}

@media (max-width: 800px) {
  .title-screen {
    justify-content: flex-start;
    align-items: center;
    padding-top: calc(var(--safe-top) + 66px);
    background:
      linear-gradient(180deg, rgba(9, 5, 20, 0.52) 0%, transparent 30%, transparent 58%, rgba(9, 5, 20, 0.72) 100%),
