  }

  .weapon-card {
    grid-column: 2;
    grid-row: 1;
    min-width: 0;
    max-width: 140px;
    padding: 7px 10px 8px;
  }

  .weapon-card strong {
    font-size: 13px;
  }

  .weapon-card > span:last-child {
    display: none;
  }

  .combo-hud {
    position: absolute;
    right: 14px;
    bottom: calc(var(--safe-bottom) + 76px);
    margin: 0;
    min-width: 86px;
  }

  .combo-x {
    font-size: 16px;
  }

  .combo-x b {
    font-size: 25px;
  }

  .aim-hint {
    bottom: calc(var(--safe-bottom) + 62px);
