    grid-template-columns: 1fr;
  }

  .weapon-item {
    min-height: 128px;
  }

  .armory-panel {
    padding: 20px 17px;
  }

  .armory-foot {
    flex-direction: column;
    align-items: stretch;
  }

  .armory-foot > span {
    text-align: center;
  }

  .modal-card {
    padding: 26px 21px 23px;
  }

  .modal-actions .primary-button,
  .modal-actions .secondary-button,
  .modal-actions .ghost-button {
