  }
}

@media (max-height: 680px) and (orientation: landscape) {
  .rotate-hint {
    position: fixed;
    z-index: 80;
    left: 50%;
    top: 14px;
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    border-radius: 999px;
    background: rgba(10, 6, 20, 0.8);
    border: 1px solid rgba(255, 255, 255, 0.12);
    color: rgba(255, 245, 214, 0.55);
    font-size: 9px;
    transform: translateX(-50%);
    pointer-events: none;
  }

  .rotate-icon {
    color: var(--yellow);
    font-size: 16px;
  }

  .rotate-hint strong {
    color: var(--cream);
    font-size: 9px;
    letter-spacing: 0.12em;
  }

  .rotate-hint span {
    display: none;
  }

  .title-screen {
    padding-top: 18px;
  }

  .title-brand {
    display: none;
  }

  .title-content {
    width: min(520px, 65vw);
  }

  .game-logo {
    font-size: clamp(54px, 10vw, 84px);
  }

  .title-tagline {
    margin: 24px 0 16px;
  }

  .title-actions {
    gap: 9px;
  }

  .control-strip {
    display: none;
  }

  .title-bottom {
    display: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

