    },
    power: {
      name: "FIREPOWER",
      icon: "×2",
      desc: "+1 projectile every 2 levels.",
      base: 76,
      growth: 1.8,
      max: 8,
    },
  };

  const ENEMY_TYPES = {
    walker: { hp: 58, speed: 46, damage: 8, scale: 1, coin: 3, score: 10, hitR: 28, label: "ROTTER" },
    runner: { hp: 38, speed: 104, damage: 7, scale: 0.9, coin: 4, score: 15, hitR: 24, label: "SPRINTER" },
    brute: { hp: 205, speed: 34, damage: 15, scale: 1.45, coin: 11, score: 40, hitR: 44, label: "BRUTE" },
    spitter: { hp: 96, speed: 38, damage: 9, scale: 1.08, coin: 8, score: 25, hitR: 30, label: "SPITTER" },
    flyer: { hp: 52, speed: 96, damage: 9, scale: 0.85, coin: 6, score: 20, hitR: 24, label: "WINGER" },
  };

  const THEME_ENEMY_COLORS = {
    wasteland: { skin: "#82c764", dark: "#315c38", cloth: "#6d3f87", metal: "#d3c69e" },
    frozen: { skin: "#a7ddeb", dark: "#32687b", cloth: "#43548f", metal: "#dff8ff" },
    magma: { skin: "#ff9d64", dark: "#8f3427", cloth: "#662336", metal: "#ffd381" },
    swamp: { skin: "#a8df6e", dark: "#426d37", cloth: "#7b3f76", metal: "#e7e08e" },
  };

  function getLevel(n) {
    const i = (n - 1) % THEMES.length;
    const tier = Math.floor((n - 1) / THEMES.length);
    const theme = THEMES[i];
    const bossBase = theme.bossName;
    const bossName = tier > 0 ? `${bossBase} ${"II".repeat(Math.min(tier, 3))}` : bossBase;
    let pool;
    if (n === 1) pool = ["walker", "walker", "walker"];
    else if (n === 2) pool = ["walker", "walker", "runner", "runner"];
    else if (n === 3) pool = ["walker", "runner", "brute", "runner", "walker"];
    else if (n === 4) pool = ["walker", "runner", "spitter", "brute", "walker"];
    else if (n === 5) pool = ["walker", "runner", "spitter", "flyer", "brute"];
    else pool = ["walker", "runner", "spitter", "flyer", "brute", "brute"];

    return {
      number: n,
      themeIndex: i,
      theme,
      stage: theme.stage + (tier ? ` ${["", "II", "III", "IV"][Math.min(tier, 3)]}` : ""),
      tagline: LEVEL_TAGLINES[i],
      bossName,
      bossKind: i,
      typePool: pool,
      duration: 31 + Math.min(18, (n - 1) * 3),
      hpMult: 1 + (n - 1) * 0.28,
      dmgMult: 1 + (n - 1) * 0.11,
      speedMult: 1 + (n - 1) * 0.025,
      bossHp: Math.round(980 * Math.pow(1.42, n - 1)),
    };
  }

  /* ------------------------------------------------------------------ */
  /* Save data                                                          */
  /* ------------------------------------------------------------------ */

  const SAVE_KEY = "gunrush.save.v1";
  const DEFAULT_SAVE = {
    coins: 30,
    sector: 1,
    bestSector: 1,
    bestScore: 0,
    upgrades: { damage: 0, rate: 0, power: 0 },
    weapon: "ripper",
    unlocked: ["ripper"],
    muted: false,
  };

  function loadSave() {
    try {
      const raw = localStorage.getItem(SAVE_KEY);
      if (!raw) return structuredClone(DEFAULT_SAVE);
      const parsed = JSON.parse(raw);
      const merged = {
        ...structuredClone(DEFAULT_SAVE),
        ...parsed,
        upgrades: { ...DEFAULT_SAVE.upgrades, ...(parsed.upgrades || {}) },
      };
      merged.unlocked = Array.isArray(parsed.unlocked) ? parsed.unlocked.filter((w) => WEAPONS[w]) : ["ripper"];
      if (!merged.unlocked.includes("ripper")) merged.unlocked.push("ripper");
      if (!WEAPONS[merged.weapon]) merged.weapon = "ripper";
      merged.coins = Math.max(0, Math.floor(merged.coins || 0));
      merged.sector = clamp(Math.floor(merged.sector || 1), 1, 99);
      merged.bestSector = clamp(Math.floor(merged.bestSector || 1), 1, 99);
      for (const key of Object.keys(UPGRADES)) {
        merged.upgrades[key] = clamp(Math.floor(merged.upgrades[key] || 0), 0, UPGRADES[key].max);
      }
      return merged;
    } catch {
      return structuredClone(DEFAULT_SAVE);
    }
  }

  const meta = loadSave();
  let saveTimer = 0;
  function saveNow() {
    try {
      localStorage.setItem(SAVE_KEY, JSON.stringify(meta));
    } catch {
      /* storage can be unavailable in private mode */
    }
  }
  function queueSave() {
    clearTimeout(saveTimer);
    saveTimer = setTimeout(saveNow, 350);
  }

  /* ------------------------------------------------------------------ */
  /* Tiny synthesized sound kit                                         */
  /* ------------------------------------------------------------------ */

  const audio = {
    ctx: null,
    enabled: !meta.muted,
    master: null,
    last: Object.create(null),

    unlock() {
      if (!this.enabled) return;
      if (!this.ctx) {
        const AC = window.AudioContext || window.webkitAudioContext;
        if (!AC) return;
        this.ctx = new AC();
        this.master = this.ctx.createGain();
        this.master.gain.value = 0.34;
        this.master.connect(this.ctx.destination);
      }
      if (this.ctx.state === "suspended") this.ctx.resume().catch(() => {});
    },

    tone(freq, dur, type = "square", vol = 0.08, slide = 0, delay = 0) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime + delay;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(freq, t);
      if (slide) osc.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(Math.max(0.001, vol), t + 0.006);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(gain);
      gain.connect(this.master);
      osc.start(t);
      osc.stop(t + dur + 0.02);
    },

    noise(dur, vol = 0.08, cutoff = 1200, delay = 0, q = 1) {
      if (!this.ctx || !this.enabled) return;
      const t = this.ctx.currentTime + delay;
      const size = Math.max(1, Math.floor(this.ctx.sampleRate * dur));
      const buffer = this.ctx.createBuffer(1, size, this.ctx.sampleRate);
      const data = buffer.getChannelData(0);
      for (let i = 0; i < size; i++) data[i] = Math.random() * 2 - 1;
      const src = this.ctx.createBufferSource();
      src.buffer = buffer;
      const filter = this.ctx.createBiquadFilter();
      filter.type = "lowpass";
      filter.frequency.setValueAtTime(cutoff, t);
      filter.frequency.exponentialRampToValueAtTime(Math.max(120, cutoff * 0.34), t + dur);
      filter.Q.value = q;
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(vol, t);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      src.connect(filter);
      filter.connect(gain);
      gain.connect(this.master);
      src.start(t);
    },

    play(name) {
      if (!this.ctx || !this.enabled) return;
      const now = this.ctx.currentTime;
      if (this.last[name] && now - this.last[name] < 0.025) return;
      this.last[name] = now;
      switch (name) {
        case "shoot":
          this.noise(0.055, 0.035, 2400);
          this.tone(155, 0.05, "square", 0.025, -60);
          break;
        case "shotgun":
          this.noise(0.12, 0.08, 1600);
          this.tone(92, 0.1, "sawtooth", 0.05, -42);
          break;
        case "plasma":
          this.tone(520, 0.12, "sine", 0.05, 380);
          this.tone(210, 0.11, "triangle", 0.035, -120);
          break;
        case "rocket":
          this.noise(0.22, 0.1, 900);
          this.tone(72, 0.25, "sawtooth", 0.06, -32);
          break;
        case "hit":
          this.tone(220, 0.035, "triangle", 0.02, -120);
          break;
        case "kill":
          this.noise(0.1, 0.045, 900);
          this.tone(130, 0.09, "square", 0.025, -75);
          break;
        case "explosion":
          this.noise(0.45, 0.25, 650);
          this.tone(58, 0.35, "sine", 0.18, -30);
          break;
        case "hurt":
          this.tone(92, 0.22, "sawtooth", 0.15, -54);
          this.noise(0.15, 0.08, 700);
          break;
        case "coin":
          this.tone(780, 0.07, "sine", 0.035, 180);
          this.tone(1180, 0.08, "sine", 0.025, 120, 0.045);
          break;
        case "heal":
          this.tone(380, 0.1, "sine", 0.035, 180);
          this.tone(620, 0.14, "sine", 0.025, 220, 0.08);
          break;
        case "ui":
          this.tone(520, 0.05, "square", 0.025, 70);
          break;
        case "buy":
          this.tone(440, 0.08, "square", 0.04, 160);
          this.tone(660, 0.11, "square", 0.035, 180, 0.07);
          break;
        case "boss":
          this.tone(57, 0.9, "sawtooth", 0.15, 20);
          this.tone(43, 1.2, "sine", 0.11, -8);
          this.noise(0.7, 0.07, 420);
          break;
        case "bossdie":
          this.noise(1.2, 0.3, 900);
          this.tone(72, 1.05, "sawtooth", 0.2, -52);
          this.tone(31, 1.4, "sine", 0.18, -10);
          break;
        case "clear":
          [523, 659, 784, 1046].forEach((f, i) => this.tone(f, 0.19, "square", 0.045, 22, i * 0.08));
          break;
      }
    },
  };

