  ctx.fillStyle = "#f0bd8e"; ctx.beginPath(); ctx.ellipse(2, -83, 13, 14, -0.08, 0, TAU); ctx.fill();
  ctx.fillStyle = "#344358"; ctx.beginPath(); ctx.ellipse(1, -88, 14, 11, -0.08, Math.PI, TAU); ctx.fill();
