657:   function damagePlayer(amount) {
658:     if (!player || player.invuln > 0 || scene !== "playing") return;
659:     const reduction = Math.min(0.38, upgradeValue("armor") * 0.035);
660:     player.hp -= amount * (1 - reduction);
661:     player.invuln = 0.68;
662:     player.hitFlash = 0.24;
663:     shake = Math.max(shake, 7);
664:     flash = Math.max(flash, 0.12);
665:     flashColor = "255,65,112";
666:     burst(player.x + 10, player.y - 42 * playerScale(), "#ff526f", 8, 150);
667:     sound("hurt");
