899:     const x = actor.x; const y = actor.y;
900:     ctx.save();
901:     ctx.translate(x, y);
902:     ctx.scale(s, s);
903:     if (actor.invuln > 0 && Math.floor(now * 18) % 2) ctx.globalAlpha = 0.55;
904:     // Ground shadow
905:     ctx.fillStyle = "rgba(8,4,16,0.42)";
906:     ctx.beginPath(); ctx.ellipse(-4, 3, 35, 8, 0, 0, TAU); ctx.fill();
