913:     ctx.beginPath(); ctx.moveTo(6, -29); ctx.lineTo(13 - stride * 7, -12); ctx.lineTo(20 - stride * 10, -2); ctx.stroke();
914:     ctx.fillStyle = "#303449"; ctx.beginPath(); ctx.roundRect(11 - stride * 10, -7, 19, 7, 3); ctx.fill();
915:     // Jacket torso
916:     ctx.fillStyle = actor.hitFlash > 0 ? "#fff0d6" : "#e4a344";
917:     ctx.beginPath(); ctx.moveTo(-14, -66); ctx.quadraticCurveTo(-3, -74, 12, -67); ctx.lineTo(19, -31); ctx.quadraticCurveTo(0, -22, -18, -32); ctx.closePath(); ctx.fill();
918:     ctx.fillStyle = "#f6c75e"; ctx.beginPath(); ctx.moveTo(-12, -63); ctx.lineTo(-2, -58); ctx.lineTo(-8, -34); ctx.lineTo(-17, -36); ctx.closePath(); ctx.fill();
919:     // Backpack
920:     ctx.fillStyle = "#50556b"; ctx.beginPath(); ctx.roundRect(-24, -65, 12, 24, 4); ctx.fill();
921:     ctx.fillStyle = "#d8ff47"; ctx.fillRect(-21, -59, 5, 6);
922:     // Neck + head
923:     ctx.fillStyle = "#d78b67"; ctx.fillRect(0, -77, 9, 12);
924:     ctx.fillStyle = "#f0bd8e"; ctx.beginPath(); ctx.ellipse(2, -83, 13, 14, -0.08, 0, TAU); ctx.fill();
925:     ctx.fillStyle = "#344358"; ctx.beginPath(); ctx.ellipse(1, -88, 14, 11, -0.08, Math.PI, TAU); ctx.fill();
926:     ctx.fillStyle = "#d9ff45"; ctx.fillRect(4, -88, 10, 4);
927:     ctx.fillStyle = "#533c42"; ctx.fillRect(-8, -81, 5, 2);
928:     // Gun and aiming arm
929:     const gunX = 7; const gunY = -56;
930:     ctx.save(); ctx.translate(gunX, gunY); ctx.rotate(actor.aimAngle || -0.15);
931:     ctx.fillStyle = "#b9c3cf"; ctx.beginPath(); ctx.roundRect(0, -5, 30, 10, 3); ctx.fill();
932:     ctx.fillStyle = "#34404f"; ctx.fillRect(8, -3, 21, 5);
933:     ctx.fillStyle = "#d9ff45"; ctx.fillRect(22, -4, 5, 2);
934:     ctx.fillStyle = "#3b4050"; ctx.beginPath(); ctx.roundRect(7, 2, 8, 11, 2); ctx.fill();
