1055:   function nearestTarget(x, y, maxDistance = Infinity) {
1056:     let best = null; let bestDist = maxDistance * maxDistance;
1057:     for (const enemy of enemies) {
1058:       if (enemy.dead) continue;
1059:       const d = (enemy.x - x) ** 2 + (enemy.y - enemy.radius * 0.6 - y) ** 2;
1060:       if (d < bestDist) { bestDist = d; best = { x: enemy.x, y: enemy.y - enemy.radius * 0.6 }; }
1061:     }
1062:     if (boss) { const d = (boss.x - x) ** 2 + (boss.y - 28 - y) ** 2; if (d < bestDist) best = { x: boss.x, y: boss.y - 28 }; }
1063:     return best;
1064:   }
