754:   function updateGame(dt) {
755:     if (scene !== "playing" || !run || !player) return;
756:     run.elapsed += dt;
757:     run.scroll += dt * 115;
758:     player.runPhase += dt * 11;
759:     player.recoil = Math.max(0, player.recoil - dt * 5.5);
760:     player.invuln = Math.max(0, player.invuln - dt);
761:     player.hitFlash = Math.max(0, player.hitFlash - dt);
762:     player.muzzle = Math.max(0, player.muzzle - dt * 7);
763:     player.muzzleBurst = Math.max(0, player.muzzleBurst - dt * 5);
764:     if (input.aiming && input.pointer) {
765:       const gunX = player.x + 37 * playerScale();
766:       const gunY = player.y - 54 * playerScale();
767:       player.desiredAim = clamp(Math.atan2(gunY - input.pointer.y, input.pointer.x - gunX), -1.32, 0.3);
768:     } else if (!input.usedAim) {
769:       const target = nearestTarget(player.x + 40, player.y - 55, 1.8);
770:       if (target) player.desiredAim = clamp(Math.atan2(target.y - player.y + 55 * playerScale(), target.x - player.x - 38 * playerScale()), -1.22, 0.22);
771:     }
772:     let angleDelta = player.desiredAim - player.aimAngle;
773:     while (angleDelta > Math.PI) angleDelta -= TAU;
774:     while (angleDelta < -Math.PI) angleDelta += TAU;
775:     player.aimAngle += angleDelta * Math.min(1, dt * 12);
776: 
777:     if (!run.bossDefeated) {
778:       if (run.spawnLeft > 0) {
779:         run.spawnTimer -= dt;
780:         if (run.spawnTimer <= 0) {
781:           enemies.push(makeEnemy()); run.spawnLeft--; run.totalSpawned++;
782:           run.spawnTimer = Math.max(0.38, rand(0.72, 1.05) - run.level.difficulty * 0.035);
783:         }
784:       } else if (enemies.length === 0 && !boss) {
785:         run.intermission += dt;
786:         if (run.intermission > 1.2) { run.intermission = 0; beginNextWave(); }
787:       }
788:     }
789: 
790:     const weapon = getWeapon();
791:     const fireRate = weapon.rate * Math.max(0.52, 1 - upgradeValue("fire") * 0.07);
792:     player.fireCd -= dt;
793:     if (player.fireCd <= 0 && !run.bossDefeated) {
794:       const muzzleX = player.x + 38 * playerScale();
795:       const muzzleY = player.y - 57 * playerScale();
796:       let fireAngle = player.aimAngle;
797:       if (!input.usedAim) {
798:         const target = nearestTarget(muzzleX, muzzleY, 2.4);
799:         if (target) fireAngle = Math.atan2(target.y - muzzleY, target.x - muzzleX);
800:       }
801:       player.fireCd = fireRate;
802:       player.recoil = 1; player.muzzle = 1; player.muzzleBurst = 1;
803:       for (let i = 0; i < weapon.pellets; i++) {
804:         const a = fireAngle + rand(-weapon.spread, weapon.spread);
805:         bullets.push({ x: muzzleX, y: muzzleY, vx: Math.cos(a) * weapon.speed, vy: Math.sin(a) * weapon.speed, damage: weapon.damage * (1 + upgradeValue("damage") * 0.12), color: weapon.color, life: 1.45, r: weapon.id === "rocket" ? 5 : 3, splash: weapon.splash || 0, chain: weapon.chain || 0, hitIds: [] });
806:       }
807:       burst(muzzleX, muzzleY, weapon.color, weapon.id === "rocket" ? 5 : 2, 55);
808:       sound("shot", weapon.id);
809:     }
810: 
811:     for (const enemy of enemies) {
812:       enemy.bob += dt * (enemy.type === "runner" ? 7 : 4);
813:       enemy.hit = Math.max(0, enemy.hit - dt);
814:       enemy.attackCd -= dt;
815:       enemy.spitCd -= dt;
816:       const targetX = player.x + 61;
817:       if (enemy.x > targetX) enemy.x -= enemy.speed * dt;
818:       else if (enemy.attackCd <= 0) { enemy.attackCd = enemy.type === "brute" ? 0.92 : 0.72; damagePlayer(enemy.damage); }
819:       if (enemy.type === "spitter" && enemy.spitCd <= 0 && enemy.x > player.x + 135 && enemy.x < view.W + 20) {
820:         enemy.spitCd = rand(2.2, 3.2);
821:         const dx = player.x + 20 - enemy.x; const dy = player.y - 45 - enemy.y;
822:         const a = Math.atan2(dy, dx);
823:         hazards.push({ x: enemy.x - 10, y: enemy.y - 20, vx: Math.cos(a) * 235, vy: Math.sin(a) * 235, life: 3, r: 7, damage: enemy.damage * 0.75, color: "#ce78b6" });
824:       }
825:     }
826: 
827:     if (boss) {
828:       boss.bob += dt * 2.6; boss.hit = Math.max(0, boss.hit - dt); boss.attackCd -= dt;
829:       boss.x = Math.max(view.W * 0.7, boss.x - 24 * dt);
830:       boss.y = view.groundY - 70 * actorScale() + Math.sin(boss.bob) * 8;
831:       if (boss.attackCd <= 0) {
832:         boss.attackCd = Math.max(0.8, 1.7 - run.level.difficulty * 0.04);
833:         const a = Math.atan2(player.y - 55 * playerScale() - boss.y, player.x + 20 - boss.x);
834:         const spread = run.level.sector > 3 ? [-0.13, 0, 0.13] : [0];
835:         for (const offset of spread) hazards.push({ x: boss.x - 36, y: boss.y - 26, vx: Math.cos(a + offset) * 290, vy: Math.sin(a + offset) * 290, life: 3, r: 10, damage: 15 + run.level.difficulty * 1.5, color: "#ff597a" });
836:         burst(boss.x - 30, boss.y - 26, "#ff597a", 5, 65); sound("spit");
837:       }
838:     }
839: 
840:     for (const bullet of bullets) {
841:       bullet.x += bullet.vx * dt; bullet.y += bullet.vy * dt; bullet.life -= dt;
842:       for (const enemy of enemies) {
843:         if (enemy.dead || bullet.hitIds.includes(enemy.id)) continue;
844:         if (Math.hypot(enemy.x - bullet.x, enemy.y - enemy.radius * 0.5 - bullet.y) < enemy.radius * 0.8 + bullet.r) {
845:           enemy.hp -= bullet.damage; enemy.hit = 0.12; bullet.life = 0;
846:           burst(bullet.x, bullet.y, bullet.color, 3, 70); sound("impact");
847:           if (bullet.splash) for (const other of enemies) if (!other.dead && other !== enemy && Math.hypot(other.x - enemy.x, other.y - enemy.y) < bullet.splash) other.hp -= bullet.damage * 0.65;
848:           if (bullet.chain) {
849:             let left = bullet.chain;
850:             for (const other of enemies) if (!other.dead && other !== enemy && Math.hypot(other.x - enemy.x, other.y - enemy.y) < 150 && left-- > 0) { other.hp -= bullet.damage * 0.65; burst(other.x, other.y - 10, "#69efff", 6, 95); }
851:           }
852:           if (enemy.hp <= 0) killEnemy(enemy);
853:           break;
854:         }
855:       }
856:       if (boss && bullet.life > 0 && Math.hypot(boss.x - bullet.x, boss.y - 28 - bullet.y) < boss.radius * 0.82 + bullet.r) { hurtBoss(bullet.damage); bullet.life = 0; burst(bullet.x, bullet.y, bullet.color, 4, 90); }
857:     }
858:     bullets = bullets.filter((bullet) => bullet.life > 0 && bullet.x < view.W + 80 && bullet.y > -30 && bullet.y < view.H + 20);
859:     enemies = enemies.filter((enemy) => !enemy.dead && enemy.x > -80);
860: 
861:     for (const hazard of hazards) {
862:       hazard.x += hazard.vx * dt; hazard.y += hazard.vy * dt; hazard.life -= dt;
863:       if (Math.hypot(hazard.x - player.x, hazard.y - (player.y - 52 * playerScale())) < hazard.r + 28 * playerScale()) { hazard.life = 0; damagePlayer(hazard.damage); burst(hazard.x, hazard.y, hazard.color, 8, 110); }
864:     }
865:     hazards = hazards.filter((hazard) => hazard.life > 0 && hazard.x > -30 && hazard.x < view.W + 30);
866: 
867:     for (const coin of pickups) {
868:       coin.phase += dt * 5; coin.vy += 360 * dt; coin.x += coin.vx * dt; coin.y += coin.vy * dt;
869:       const magnet = 100 + upgradeValue("magnet") * 45;
870:       const distance = Math.hypot(player.x - coin.x, player.y - coin.y);
871:       if (distance < magnet) { const force = (1 - distance / magnet) * 580; coin.vx += (player.x - coin.x) / Math.max(1, distance) * force * dt; coin.vy += (player.y - coin.y) / Math.max(1, distance) * force * dt; }
872:       if (distance < 45 * playerScale()) { run.coins += coin.value; coin.life = 0; burst(coin.x, coin.y, "#ffe66d", 4, 75); floatText(player.x, player.y - 110, `+${coin.value}`, "#ffe66d"); sound("coin"); }
873:       coin.life -= dt;
874:     }
875:     pickups = pickups.filter((coin) => coin.life > 0 && coin.y < view.H + 30);
876: 
877:     for (const part of particles) { part.life -= dt; part.x += part.vx * dt; part.y += part.vy * dt; part.vx *= Math.pow(0.1, dt); part.vy += (part.gravity || 0) * dt; }
878:     particles = particles.filter((part) => part.life > 0);
879:     for (const floater of floaters) { floater.life -= dt; floater.y -= 30 * dt; }
880:     floaters = floaters.filter((floater) => floater.life > 0);
881:     run.comboTimer -= dt;
882:     if (run.comboTimer <= 0) run.combo = 0;
883:     shake = Math.max(0, shake - dt * 24);
884:     flash = Math.max(0, flash - dt * 1.8);
885:     if (hintTimer > 0) hintTimer -= dt;
886:     if (bannerTimer > 0 && (bannerTimer -= dt) <= 0) ui.banner.classList.remove("show");
887:     if (toastTimer > 0 && (toastTimer -= dt) <= 0) ui.toast.classList.remove("show");
888:     updateHUD();
889:   }
