646:   function beginNextWave() {
647:     if (run.wave < run.waves) {
648:       run.wave++;
649:       run.waveKills = 0;
650:       run.waveGoal = 6 + Math.min(5, Math.floor(meta.sector / 2)) + run.wave;
651:       run.spawnLeft = run.waveGoal;
652:       run.spawnTimer = 0.7;
653:       showBanner(`WAVE ${run.wave} / ${run.waves}`, "KEEP MOVING", "THE HORDE IS GETTING CLOSER");
654:     } else spawnBoss();
655:   }
