671:   function killEnemy(enemy) {
672:     if (enemy.dead) return;
673:     enemy.dead = true;
674:     run.kills++;
675:     run.waveKills++;
676:     run.combo++;
677:     run.comboTimer = 2.15;
678:     run.bestCombo = Math.max(run.bestCombo, run.combo);
679:     const payout = enemy.type === "brute" ? 5 : 3;
680:     const bonus = run.combo > 1 && run.combo % 5 === 0 ? 5 : 0;
681:     dropCoins(enemy.x, enemy.y - 12, payout + bonus);
682:     burst(enemy.x, enemy.y - enemy.radius * 0.55, enemy.color, enemy.type === "brute" ? 15 : 10, 190);
683:     floatText(enemy.x, enemy.y - enemy.radius, `+${payout + bonus}`, "#ffe66d");
684:     shake = Math.max(shake, enemy.type === "brute" ? 4 : 2);
685:     sound("kill");
686:   }
