730:   function finishRun(won) {
731:     if (scene !== "playing") return;
732:     if (won) {
733:       meta.coins += run.coins;
734:       meta.sector = Math.max(meta.sector, run.level.sector + 1);
735:       meta.bestSector = Math.max(meta.bestSector, meta.sector);
736:       saveMeta(); updateMetaUI();
737:       ui.clearSector.textContent = pad2(run.level.sector);
738:       ui.clearBossLine.textContent = `${run.level.boss} has been erased. The next road is calling.`;
739:       ui.clearKills.textContent = run.kills;
740:       ui.clearCoins.textContent = run.coins;
741:       ui.clearCombo.textContent = run.bestCombo;
742:       setScene("clear");
743:       sound("clear");
744:     } else {
745:       meta.coins += run.coins;
746:       saveMeta(); updateMetaUI();
747:       ui.deadSector.textContent = pad2(run.level.sector);
748:       ui.deadKills.textContent = run.kills;
749:       ui.deadCoins.textContent = run.coins;
750:       setScene("dead");
751:     }
752:   }
