690:     boss.hp -= damage;
691:     boss.hit = 0.11;
692:     if (boss.hp <= 0) {
693:       boss.hp = 0;
694:       burst(boss.x, boss.y - 45, "#ffb04e", 42, 300);
695:       burst(boss.x, boss.y - 45, "#ff4e83", 28, 250);
696:       dropCoins(boss.x, boss.y - 25, 55 + meta.sector * 5);
697:       run.coins += 55 + meta.sector * 5;
698:       floatText(boss.x, boss.y - 100, "BOSS DOWN!", "#d9ff45");
699:       boss = null;
700:       run.bossDefeated = true;
701:       ui.bossHud.classList.remove("active");
702:       ui.waveHud.classList.remove("boss-wave");
703:       shake = 18; flash = 0.22; flashColor = "255,219,89";
704:       sound("bossdown");
705:       window.setTimeout(() => { if (scene === "playing" && run?.bossDefeated) finishRun(true); }, 900);
706:     }
707:   }
