709:   function dropCoins(x, y, amount) {
710:     const count = amount >= 20 ? 5 : amount >= 5 ? 2 : 1;
711:     const each = Math.floor(amount / count);
712:     let left = amount;
713:     for (let i = 0; i < count; i++) {
714:       const value = i === count - 1 ? left : each;
715:       left -= value;
716:       pickups.push({ x: x + rand(-10, 10), y: y + rand(-10, 8), vx: rand(-60, 25), vy: rand(-170, -70), value, life: 9, r: 7, phase: rand(0, TAU) });
717:     }
718:   }
