1002:   function drawWorld(now) {
1003:     if (!backdrop) buildBackdrop();
1004:     ctx.setTransform(view.DPR, 0, 0, view.DPR, 0, 0);
1005:     ctx.fillStyle = "#100b21"; ctx.fillRect(0, 0, view.W, view.H);
1006:     const shakeX = shake ? rand(-shake, shake) : 0; const shakeY = shake ? rand(-shake * 0.5, shake * 0.5) : 0;
1007:     ctx.save(); ctx.translate(shakeX, shakeY);
1008:     ctx.drawImage(backdrop, 0, 0, view.W, view.H);
1009:     drawScenery(run ? run.scroll : menu.scroll, 0);
1010:     if (scene === "playing" || ["paused", "clear", "dead"].includes(scene)) {
1011:       const sorted = enemies.slice().sort((a, b) => a.y - b.y);
1012:       for (const enemy of sorted) drawEnemy(enemy);
1013:       drawBoss();
1014:       for (const hazard of hazards) {
