637:   function spawnBoss() {
638:     boss = { x: view.W + 110, y: view.groundY - 65 * actorScale(), hp: 950 * run.level.difficulty, maxHp: 950 * run.level.difficulty, radius: 58 * actorScale(), attackCd: 1.5, phase: 0, hit: 0, bob: 0, name: run.level.boss };
639:     ui.bossName.textContent = boss.name;
640:     ui.bossHud.classList.add("active");
641:     ui.waveHud.classList.add("boss-wave");
642:     showBanner("FINAL WAVE", boss.name, "IT'S BIG. MAKE IT SMALLER.");
