587:   function startRun(sector = meta.sector) {
588:     meta.sector = Math.max(1, sector);
589:     meta.bestSector = Math.max(meta.bestSector || 1, meta.sector);
590:     saveMeta();
591:     const armor = upgradeValue("armor");
592:     player = makePlayer();
593:     player.maxHp = 120 + armor * 15;
594:     player.hp = player.maxHp;
595:     player.aimAngle = -0.22;
596:     player.desiredAim = player.aimAngle;
597:     run = { level: getLevel(meta.sector), wave: 1, waves: 3, waveKills: 0, waveGoal: 6 + Math.min(5, Math.floor(meta.sector / 2)), spawnLeft: 6 + Math.min(5, Math.floor(meta.sector / 2)), spawnTimer: 0.6, intermission: 0, kills: 0, coins: 0, bestCombo: 0, combo: 0, comboTimer: 0, elapsed: 0, scroll: 0, totalSpawned: 0, bossDefeated: false, lastShot: 0 };
598:     enemies = []; bullets = []; hazards = []; pickups = []; particles = []; floaters = []; boss = null;
599:     shake = 0; flash = 0; hitStop = 0; hintTimer = 7; input.usedAim = false;
600:     backdrop = null;
601:     buildBackdrop();
602:     setScene("playing");
603:     ui.hud.setAttribute("aria-hidden", "false");
604:     updateMetaUI();
605:     updateHUD();
606:     showBanner(`SECTOR ${pad2(meta.sector)}`, run.level.stage, "SURVIVE THE HORDE");
607:     sound("start");
608:   }
