626:   function makeEnemy() {
627:     const d = run.level.difficulty;
628:     const roll = Math.random();
629:     const type = roll < 0.58 ? "runner" : roll < 0.84 ? "brute" : "spitter";
630:     const stats = type === "runner" ? { hp: 34, speed: 49, damage: 9, radius: 19, color: "#91d95e" }
631:       : type === "brute" ? { hp: 76, speed: 26, damage: 17, radius: 26, color: "#d88752" }
632:         : { hp: 46, speed: 34, damage: 8, radius: 21, color: "#c675b6" };
633:     const y = view.groundY - rand(8, Math.min(115, view.H * 0.18));
634:     return { id: uid++, type, x: view.W + rand(30, 115), y, hp: stats.hp * d, maxHp: stats.hp * d, speed: stats.speed * (1 + (d - 1) * 0.22), damage: stats.damage * (1 + (d - 1) * 0.12), radius: stats.radius * actorScale(), color: stats.color, hit: 0, attackCd: rand(0.35, 1.1), bob: rand(0, TAU), dead: false, spitCd: rand(1.7, 3.4), knock: 0 };
635:   }
