720:   function burst(x, y, color, count = 10, force = 150) {
721:     for (let i = 0; i < count; i++) {
722:       const angle = rand(0, TAU); const speed = rand(force * 0.22, force);
723:       particles.push({ x, y, vx: Math.cos(angle) * speed, vy: Math.sin(angle) * speed, life: rand(0.22, 0.62), maxLife: 0.62, size: rand(2, 5), color, gravity: 260 });
724:     }
725:     particles.push({ x, y, vx: 0, vy: 0, life: 0.22, maxLife: 0.22, size: 12, color, ring: true });
726:   }
