909:     ctx.beginPath(); ctx.moveTo(-8, -28); ctx.lineTo(-16 + stride * 7, -10); ctx.lineTo(-19 + stride * 10, -2); ctx.stroke();
910:     ctx.fillStyle = "#22283d"; ctx.beginPath(); ctx.roundRect(-26 + stride * 10, -7, 17, 7, 3); ctx.fill();
