425:   function drawScenery(scroll, dt) {
426:     const theme = THEMES[((run ? run.level.themeIndex : meta.sector - 1) % THEMES.length)];
427:     const W = view.W;
428:     const H = view.H;
429:     const ground = view.groundY;
430:     const horizon = view.horizonY;
431: 
432:     // Low ruins and dead trees, scrolling slower than the ground.
433:     const ruinGap = W < 620 ? 160 : 230;
434:     const ruinOffset = scroll * 0.1 % ruinGap;
435:     ctx.save();
436:     for (let i = -1; i < W / ruinGap + 2; i++) {
437:       const x = i * ruinGap - ruinOffset;
438:       const r = hash(i * 7.7 + 3);
439:       const h = 35 + r * 85;
440:       const w = 18 + hash(i * 3.2) * 30;
441:       ctx.fillStyle = "rgba(13, 7, 24, 0.32)";
442:       ctx.fillRect(x, horizon + 12 - h, w, h);
443:       if (r > 0.5) {
444:         ctx.fillRect(x + w * 0.25, horizon + 12 - h - 15, 4, 15);
445:         ctx.fillRect(x + w * 0.25 - 3, horizon + 12 - h - 16, 10, 3);
446:       }
447:       // A few window lights.
448:       ctx.fillStyle = `rgba(255, 214, 122, ${0.08 + r * 0.09})`;
449:       ctx.fillRect(x + 5, horizon + 12 - h + 10, 3, 5);
450:       if (r > 0.4) ctx.fillRect(x + w - 8, horizon + 12 - h + 25, 3, 5);
451:     }
452:     ctx.restore();
453: 
454:     // Utility poles in the middle distance.
455:     const poleGap = W < 620 ? 155 : 210;
456:     const poleOffset = scroll * 0.34 % poleGap;
457:     ctx.save();
458:     for (let i = -1; i < W / poleGap + 2; i++) {
459:       const x = i * poleGap - poleOffset;
460:       const h = 55 + hash(i * 4.2) * 35;
461:       ctx.strokeStyle = "rgba(12, 8, 22, 0.46)";
462:       ctx.lineWidth = 3;
463:       ctx.beginPath();
464:       ctx.moveTo(x, horizon + 18);
465:       ctx.lineTo(x, horizon + 18 - h);
466:       ctx.moveTo(x - 11, horizon + 10 - h);
467:       ctx.lineTo(x + 11, horizon + 10 - h);
468:       ctx.stroke();
469:       ctx.strokeStyle = "rgba(12, 8, 22, 0.18)";
470:       ctx.lineWidth = 1;
471:       ctx.beginPath();
472:       ctx.moveTo(x + 11, horizon + 10 - h);
473:       ctx.quadraticCurveTo(x + poleGap * 0.5, horizon - h * 0.15, x + poleGap, horizon + 10 - h);
474:       ctx.stroke();
475:     }
476:     ctx.restore();
477: 
478:     // Ground slab.
479:     const groundGrad = ctx.createLinearGradient(0, horizon, 0, H);
480:     groundGrad.addColorStop(0, theme.groundTop);
481:     groundGrad.addColorStop(0.36, theme.ground);
482:     groundGrad.addColorStop(1, theme.groundDeep);
483:     ctx.fillStyle = groundGrad;
484:     ctx.fillRect(0, horizon + 5, W, H - horizon);
485: 
486:     // Horizon rim light.
487:     const rim = ctx.createLinearGradient(0, horizon - 3, 0, horizon + 22);
488:     rim.addColorStop(0, "rgba(255,255,255,0)");
489:     rim.addColorStop(0.45, theme.haze);
490:     rim.addColorStop(1, "rgba(255,255,255,0)");
491:     ctx.fillStyle = rim;
492:     ctx.fillRect(0, horizon - 3, W, 26);
493: 
494:     // The running lane. Its motion is the strongest cue that the hero is moving.
495:     const laneY = ground + 6;
496:     ctx.fillStyle = "rgba(8, 5, 15, 0.24)";
497:     ctx.fillRect(0, laneY, W, H - laneY);
498:     const scrollFast = scroll * 1.18;
499:     const dashGap = W < 620 ? 88 : 128;
500:     const dashOff = scrollFast % dashGap;
501:     for (let i = -1; i < W / dashGap + 2; i++) {
502:       const x = i * dashGap - dashOff;
503:       const y = laneY + 18 + (i % 2) * 19;
504:       ctx.fillStyle = "rgba(255, 245, 214, 0.085)";
505:       ctx.beginPath();
506:       ctx.moveTo(x + 11, y);
507:       ctx.lineTo(x + 57, y);
508:       ctx.lineTo(x + 52, y + 4);
509:       ctx.lineTo(x + 7, y + 4);
510:       ctx.closePath();
511:       ctx.fill();
512:     }
513: 
514:     // Scrolling stones and grass tufts.
515:     const pebbleGap = 58;
516:     const pebbleOff = scrollFast * 1.6 % pebbleGap;
517:     for (let i = -1; i < W / pebbleGap + 2; i++) {
518:       const x = i * pebbleGap - pebbleOff;
519:       const r = hash(i * 5.4 + 9);
520:       const y = ground + 24 + r * (H - ground - 33);
521:       ctx.fillStyle = r > 0.5 ? "rgba(255, 221, 174, 0.09)" : "rgba(0,0,0,0.2)";
522:       ctx.beginPath();
523:       ctx.ellipse(x, y, 3 + r * 8, 1.5 + r * 3.5, 0, 0, TAU);
524:       ctx.fill();
525:     }
526: 
527:     const tuftGap = 43;
528:     const tuftOff = scroll * 1.4 % tuftGap;
529:     for (let i = -1; i < W / tuftGap + 2; i++) {
530:       const x = i * tuftGap - tuftOff;
531:       const r = hash(i * 8.3 + 1);
532:       if (r < 0.25) continue;
533:       const h = 5 + r * 11;
534:       ctx.strokeStyle = theme.grass;
535:       ctx.globalAlpha = 0.22 + r * 0.3;
536:       ctx.lineWidth = 1.6;
537:       ctx.beginPath();
538:       ctx.moveTo(x, ground + 8);
539:       ctx.quadraticCurveTo(x - 3, ground + 8 - h * 0.6, x - 5 - r * 4, ground + 8 - h);
540:       ctx.moveTo(x + 2, ground + 8);
541:       ctx.quadraticCurveTo(x + 4, ground + 8 - h * 0.5, x + 3 + r * 3, ground + 8 - h * 0.8);
542:       ctx.stroke();
543:     }
544:     ctx.globalAlpha = 1;
545: 
546:     // Tiny drifting spores / fireflies.
547:     for (let i = 0; i < 14; i++) {
548:       const x = (hash(i * 2.2) * W + worldTime * (8 + hash(i) * 8)) % W;
549:       const y = horizon + 20 + hash(i * 7.1) * (H - horizon - 50);
550:       const a = 0.12 + Math.sin(worldTime * 1.4 + i) * 0.08;
551:       ctx.fillStyle = `rgba(255, 233, 168, ${Math.max(0, a)})`;
552:       ctx.beginPath();
553:       ctx.arc(x, y, 1 + hash(i * 9) * 1.5, 0, TAU);
554:       ctx.fill();
555:     }
556: 
557:     drawForegroundGrass(scroll, theme);
558:   }
