560:   function drawForegroundGrass(scroll, theme) {
561:     const W = view.W;
562:     const H = view.H;
563:     const gap = 175;
564:     const off = (scroll * 1.9) % gap;
565:     ctx.save();
566:     for (let i = -1; i < W / gap + 2; i++) {
567:       const x = i * gap - off;
568:       const r = hash(i * 6.6 + 2);
569:       const h = 24 + r * 42;
570:       ctx.globalAlpha = 0.32;
571:       ctx.strokeStyle = theme.grass;
572:       ctx.lineWidth = 2.2;
573:       ctx.beginPath();
574:       ctx.moveTo(x, H + 4);
575:       ctx.quadraticCurveTo(x - 8, H - h * 0.65, x - 22 - r * 14, H - h);
576:       ctx.moveTo(x + 4, H + 4);
577:       ctx.quadraticCurveTo(x + 14, H - h * 0.7, x + 26 + r * 12, H - h * 0.74);
578:       ctx.stroke();
579:     }
580:     ctx.restore();
581:   }
