1022:         ctx.fillStyle = "#fff8d5"; ctx.beginPath(); ctx.arc(bullet.x, bullet.y, bullet.r, 0, TAU); ctx.fill();
1023:       }
1024:       for (const coin of pickups) {
1025:         const bob = Math.sin(coin.phase) * 3;
1026:         ctx.fillStyle = "#c87811"; ctx.beginPath(); ctx.arc(coin.x, coin.y + bob, coin.r, 0, TAU); ctx.fill();
1027:         ctx.fillStyle = "#ffe362"; ctx.beginPath(); ctx.arc(coin.x, coin.y + bob - 1, coin.r - 2, 0, TAU); ctx.fill();
1028:         ctx.fillStyle = "#fff4b1"; ctx.fillRect(coin.x - 1, coin.y + bob - 4, 2, 7);
1029:       }
1030:       if (player) drawPlayer(player, now);
1031:       for (const part of particles) {
1032:         const alpha = clamp(part.life / part.maxLife, 0, 1);
1033:         ctx.globalAlpha = alpha; ctx.strokeStyle = part.color; ctx.fillStyle = part.color;
1034:         if (part.ring) { ctx.lineWidth = 2; ctx.beginPath(); ctx.arc(part.x, part.y, part.size * (1.4 - alpha), 0, TAU); ctx.stroke(); }
1035:         else { ctx.beginPath(); ctx.arc(part.x, part.y, Math.max(0.7, part.size * alpha), 0, TAU); ctx.fill(); }
1036:       }
